package qanda.backend.content

import jakarta.servlet.http.HttpServletRequest
import org.springframework.web.bind.annotation.*
import qanda.backend.identity.Sessions
import qanda.backend.platform.http.*
import qanda.backend.platform.security.*
import java.util.UUID

@RestController
@RequestMapping("/api/v1",produces=["application/json"])
class ContentController(private val service: ContentService,private val sessions: Sessions,private val commands: Commands) {
    @GetMapping("/question-banks") fun banks(@RequestParam(required=false) subjectId: UUID?,@RequestParam(required=false) keyword: String?,@RequestParam(defaultValue="1") page: Int,@RequestParam(defaultValue="20") pageSize: Int): Page<BankView> = service.banks(sessions.student(),subjectId,keyword,PageSpec(page,pageSize))
    @GetMapping("/question-banks/{id}") fun bank(@PathVariable id: UUID): BankView=service.bank(sessions.student(),id)
    @GetMapping("/question-banks/{id}/chapters") fun chapters(@PathVariable id: UUID): List<ChapterView> = service.chapters(sessions.student(),id)
    @GetMapping("/question-banks/{id}/questions") fun questions(@PathVariable id: UUID,@RequestParam(required=false) chapterId: UUID?,@RequestParam(required=false) keyword: String?,@RequestParam(defaultValue="1") page: Int,@RequestParam(defaultValue="20") pageSize: Int): Page<QuestionView> = service.questions(sessions.student(),id,chapterId,keyword,PageSpec(page,pageSize))
    @GetMapping("/questions") fun search(@RequestParam keyword: String,@RequestParam(defaultValue="1") page: Int,@RequestParam(defaultValue="20") pageSize: Int): Page<QuestionView> = service.search(sessions.student(),keyword,PageSpec(page,pageSize))
    @GetMapping("/questions/{id}") fun question(@PathVariable id: UUID): QuestionView=service.question(sessions.student(),id)
    @GetMapping("/admin/question-banks") fun adminBanks(@RequestParam(required=false) subjectId: UUID?,@RequestParam(required=false) keyword: String?,@RequestParam(defaultValue="1") page: Int,@RequestParam(defaultValue="20") pageSize: Int): Page<BankView> = service.banks(sessions.admin(),subjectId,keyword,PageSpec(page,pageSize))
    @GetMapping("/admin/question-banks/{id}") fun adminBank(@PathVariable id: UUID): BankView=service.bank(sessions.admin(),id)
    @GetMapping("/admin/question-banks/{id}/chapters") fun adminChapters(@PathVariable id: UUID): List<ChapterView> = service.chapters(sessions.admin(),id)
    @GetMapping("/admin/question-banks/{id}/questions") fun adminQuestions(@PathVariable id: UUID,@RequestParam(required=false) chapterId: UUID?,@RequestParam(required=false) keyword: String?,@RequestParam(defaultValue="1") page: Int,@RequestParam(defaultValue="20") pageSize: Int): Page<QuestionView> = service.questions(sessions.admin(),id,chapterId,keyword,PageSpec(page,pageSize))
    @GetMapping("/admin/questions/{id}") fun adminQuestion(@PathVariable id: UUID): QuestionView=service.question(sessions.admin(),id)
    @PostMapping("/admin/question-banks") fun createBank(@RequestBody input: BankInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin(true);return commands.run(a,key,"CREATE_BANK",input,MutationResult::class.java,r.requestId()) { service.saveBank(a,null,input) } }
    @PutMapping("/admin/question-banks/{id}") fun updateBank(@PathVariable id: UUID,@RequestBody input: BankInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"UPDATE_BANK:$id",input,MutationResult::class.java,r.requestId()) { service.saveBank(a,id,input) } }
    @PutMapping("/admin/question-banks/{id}/publication") fun publish(@PathVariable id: UUID,@RequestBody input: PublicationInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"PUBLISH_BANK:$id",input,MutationResult::class.java,r.requestId()) { service.publish(a,id,input) } }
    @PostMapping("/admin/question-banks/{id}/chapters") fun createChapter(@PathVariable id: UUID,@RequestBody input: ChapterInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"CREATE_CHAPTER:$id",input,MutationResult::class.java,r.requestId()) { service.saveChapter(a,id,null,input) } }
    @PutMapping("/admin/question-banks/{bankId}/chapters/{id}") fun updateChapter(@PathVariable bankId: UUID,@PathVariable id: UUID,@RequestBody input: ChapterInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"UPDATE_CHAPTER:$id",input,MutationResult::class.java,r.requestId()) { service.saveChapter(a,bankId,id,input) } }
    @DeleteMapping("/admin/question-banks/{bankId}/chapters/{id}") fun deleteChapter(@PathVariable bankId: UUID,@PathVariable id: UUID,@RequestParam expectedVersion: Long,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"DELETE_CHAPTER:$id",expectedVersion,MutationResult::class.java,r.requestId()) { service.deleteChapter(a,bankId,id,expectedVersion) } }
    @PutMapping("/admin/question-banks/{id}/chapter-order") fun reorder(@PathVariable id: UUID,@RequestBody input: ReorderInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"REORDER_CHAPTERS:$id",input,MutationResult::class.java,r.requestId()) { service.reorder(a,id,input) } }
    @PostMapping("/admin/questions") fun createQuestion(@RequestBody input: QuestionInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"CREATE_QUESTION",input,MutationResult::class.java,r.requestId()) { service.saveQuestion(a,null,input) } }
    @PutMapping("/admin/questions/{id}") fun updateQuestion(@PathVariable id: UUID,@RequestBody input: QuestionInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"UPDATE_QUESTION:$id",input,MutationResult::class.java,r.requestId()) { service.saveQuestion(a,id,input) } }
    @DeleteMapping("/admin/questions/{id}") fun deactivateQuestion(@PathVariable id: UUID,@RequestParam expectedVersion: Long,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): MutationResult { val a=sessions.admin();return commands.run(a,key,"DEACTIVATE_QUESTION:$id",expectedVersion,MutationResult::class.java,r.requestId()) { service.deactivateQuestion(a,id,expectedVersion) } }
    @PostMapping("/admin/question-banks/{id}/import-preview") fun preview(@PathVariable id: UUID,@RequestBody input: ImportInput): ImportPreview=service.preview(sessions.admin(),id,input)
    @PostMapping("/admin/question-banks/{id}/imports") fun importQuestions(@PathVariable id: UUID,@RequestBody input: ImportInput,@RequestHeader("Idempotency-Key") key: UUID,r: HttpServletRequest): ImportView { val a=sessions.admin();return commands.run(a,key,"IMPORT_QUESTIONS:$id",input,ImportView::class.java,r.requestId()) { service.import(a,id,input) } }
}
